			/**
			 * 설문발송 PARAM
			 */
			function qustnbSndngParamInfo() {
			    
			    var dmSearch = app.lookup("dmSearch");
			    
			    var dsQustnbTmptIdList = app.lookup("dsQustnbTmptIdList"); // 설문지텝플릿아이디
			    var dsQustnbSndngList = app.lookup("dsQustnbSndngList");
			    dsQustnbSndngList.clear();
			    
			    for (var i = 0; i < 2; i++) {
			        
			        if (i == 0) {
			            // 청소년 설문지
			            dsQustnbSndngList.addRow();
			            dsQustnbSndngList.setValue(i, "QUSTNB_TMPT_MNG_NO", dsQustnbTmptIdList.getValue(i, "QUSTNB_TMPT_MNG_NO"));
			            dsQustnbSndngList.setValue(i, "RCPTN_MBL_TELNO", dmSearch.getValue("TRPR_MBL_TELNO"));
			            dsQustnbSndngList.setValue(i, "RCPTN_NM", dmSearch.getValue("TRPR_NM"));
			            dsQustnbSndngList.setValue(i, "TRPR_REL_SE_CD", "11");
			        } else if (i == 1) {
			            // 보호자 설문지
			            dsQustnbSndngList.addRow();
			            dsQustnbSndngList.setValue(i, "QUSTNB_TMPT_MNG_NO", dsQustnbTmptIdList.getValue(i, "QUSTNB_TMPT_MNG_NO"));
			            
			            dsQustnbSndngList.setValue(i, "RCPTN_MBL_TELNO", dmSearch.getValue("PRTCR_MBL_TELNO"));
			            
			            // 보호자 이름이 빈값이면 "보호자" 로 셋팅
			            if (dmSearch.getValue("PRTCR_NM").toString() == "" || dmSearch.getValue("PRTCR_NM") == null) {
			                dsQustnbSndngList.setValue(i, "RCPTN_NM", "보호자");
			            } else {
			                dsQustnbSndngList.setValue(i, "RCPTN_NM", dmSearch.getValue("PRTCR_NM"));
			            }
			            
			            dsQustnbSndngList.setValue(i, "TRPR_REL_SE_CD", "12");
			        }
			    }
			    
			    console.log("설문발송 PARAM");
			    console.log(dsQustnbSndngList.getRowDataRanged());
			    
			}

