			/**
			 * 설문지미리보기(확인) 팝업
			 */
			function openSurvshtDtlPopup(index) {
			    
			    var dmSearch = app.lookup("dmSearch");
			    var dsQustnbTmptIdList = app.lookup("dsQustnbTmptIdList"); // 설문지텝플릿아이디
			    var dsQustnbMngNoCreateTrprList = app.lookup("dsQustnbMngNoCreateTrprList"); // 청소년 설문지관리번호
			    var dsQustnbMngNoCreatePrtcrList = app.lookup("dsQustnbMngNoCreatePrtcrList"); // 보호자 설문지관리번호
			    
			    var qustnbTmptMngNo = "";
			    var qustnbMngNo = "";
			    
			    if (index == 0) {
			        // 청소년
			        qustnbTmptMngNo = dsQustnbTmptIdList.getValue(0, "QUSTNB_TMPT_MNG_NO");
			        qustnbMngNo = dsQustnbMngNoCreateTrprList.getValue(0, "QUSTNB_MNG_NO");
			    } else if (index == 1) {
			        // 보호자
			        qustnbTmptMngNo = dsQustnbTmptIdList.getValue(1, "QUSTNB_TMPT_MNG_NO");
			        qustnbMngNo = dsQustnbMngNoCreatePrtcrList.getValue(0, "QUSTNB_MNG_NO");
			    }
			    
			    console.log("qustnbMngNo = " + qustnbMngNo);
			    
			    var initValue = {
			        "QUSTNB_MNG_NO": qustnbMngNo,
			        "QUSTNB_TMPT_MNG_NO": qustnbTmptMngNo,
			        "UNT_TASKWK_SE_CD": dmSearch.getValue("UNT_TASKWK_SE_CD"),
			        "SXDC_SE_CD": dmSearch.getValue("SXDC_SE_CD"),
			        "USER_ID": dmSearch.getValue("USER_ID"),
			        "MNGR_YN": "Y",
			        
			    };
			    
			    util.Dialog.open(app, "app/itgcm/outsdsrvyptcptn/CmmnsSurvshtDtlPopup", "설문지 미리보기", 940, 760, function( /*cpr.events.CUIEvent*/ e) {
			        
			        /*
			         * 다이얼로그 close 이벤트 핸들러(닫기 동작시 반환되는 값에 대한 처리)
			         * 다이얼로그가 이미 닫혀진 상태이기 때문에 다이얼로그 관련 이벤트리스너는 발생하지 않습니다.
			         */
			        /**@type cpr.controls.Dialog*/
			        var dialog = e.control;
			        var returnValue = dialog.returnValue;
			        
			        /*
			         * returnValue 처리
			         * returnValue가 단일값을 경우 그대로 사용할 수 있으며, JSON 데이터일 경우 key값을 통해 value를 받을 수 있습니다. 
			         */
			        if (!ValueUtil.isNull(returnValue)) {
			            // 자원분류관리 목록 > 자원분류관리 등록 저장한 경우  > 팝업 닫을시 자원분류관리 select box 재 조회 갱신
			            
			            if (returnValue == "save") {
			                //popUpSaveYn = "Y";
			                //getData();
			                //isSave = true;
			                console.log("설문확인 저장 : returnValue ====== " + returnValue);
			                //doDtl("save");
			                chkTrprCreateQustnbMngNoYn();
			            }
			            
			        }
			        
			    }, initValue);
			}

